package com.farika.soundflow;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.*;import java.time.Duration;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.lang.reflect.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=android.app.Application.class)
public class MemoryGestures164Test {
 ActivityController<Activity> ctrl;Activity a;
 @Before public void setup(){ctrl=Robolectric.buildActivity(Activity.class).setup();a=ctrl.get();}
 @After public void cleanup(){ctrl.pause().stop().destroy();}
 void size(View v,int w,int h){v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);}
 void send(View v,int action,float x,float y){MotionEvent e=MotionEvent.obtain(0,SystemClock.uptimeMillis(),action,x,y,0);v.dispatchTouchEvent(e);e.recycle();}
 HoldListView list(AtomicInteger held,AtomicInteger clicked){HoldListView list=new HoldListView(a);list.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_list_item_1,new String[]{"first","second","third"}));list.setOnItemClickListener((p,v,pos,id)->clicked.incrementAndGet());list.setOnItemLongClickListener((p,v,pos,id)->{held.incrementAndGet();return true;});a.setContentView(list);size(list,400,600);return list;}
 @Test public void menuOpensBeforePointerUp(){AtomicInteger held=new AtomicInteger(),clicked=new AtomicInteger();HoldListView list=list(held,clicked);send(list,MotionEvent.ACTION_DOWN,30,25);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(HoldListView.HOLD_MS+10));assertEquals(1,held.get());assertEquals(0,clicked.get());send(list,MotionEvent.ACTION_UP,30,25);Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(1,held.get());assertEquals(0,clicked.get());}
 @Test public void scrollCancelsLongPress(){AtomicInteger held=new AtomicInteger(),clicked=new AtomicInteger();HoldListView list=list(held,clicked);send(list,MotionEvent.ACTION_DOWN,30,25);send(list,MotionEvent.ACTION_MOVE,30,100);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(600));assertEquals(0,held.get());send(list,MotionEvent.ACTION_CANCEL,30,100);}
 @Test public void shortTapDoesNotOpenMenu(){AtomicInteger held=new AtomicInteger(),clicked=new AtomicInteger();HoldListView list=list(held,clicked);send(list,MotionEvent.ACTION_DOWN,30,25);send(list,MotionEvent.ACTION_UP,30,25);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(600));assertEquals(0,held.get());assertEquals(1,clicked.get());}
 @Test public void cancelledHoldDoesNotOpenMenu(){AtomicInteger held=new AtomicInteger(),clicked=new AtomicInteger();HoldListView list=list(held,clicked);send(list,MotionEvent.ACTION_DOWN,30,25);send(list,MotionEvent.ACTION_CANCEL,30,25);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(600));assertEquals(0,held.get());}
 PullRefreshLayout pull(AtomicBoolean allowed,AtomicInteger refreshed){PullRefreshLayout layout=new PullRefreshLayout(a,allowed::get,refreshed::incrementAndGet);View child=new View(a);child.setClickable(true);layout.addView(child,0,new android.widget.FrameLayout.LayoutParams(-1,-1));a.setContentView(layout);size(layout,400,600);return layout;}
 @Test public void downSwipeAtTopRefreshesExactlyOnce(){AtomicInteger count=new AtomicInteger();PullRefreshLayout p=pull(new AtomicBoolean(true),count);send(p,0,100,40);send(p,2,100,160);send(p,1,100,160);assertEquals(1,count.get());assertTrue(p.refreshing());send(p,0,100,40);send(p,2,100,160);send(p,1,100,160);assertEquals(1,count.get());p.finish();assertFalse(p.refreshing());}
 @Test public void swipeInsideScrolledListDoesNotRefresh(){AtomicInteger count=new AtomicInteger();PullRefreshLayout p=pull(new AtomicBoolean(false),count);send(p,0,100,40);send(p,2,100,180);send(p,1,100,180);assertEquals(0,count.get());}
 @Test public void horizontalGestureDoesNotRefresh(){AtomicInteger count=new AtomicInteger();PullRefreshLayout p=pull(new AtomicBoolean(true),count);send(p,0,40,80);send(p,2,220,85);send(p,1,220,85);assertEquals(0,count.get());}
 @Test public void shortPullDoesNotRefresh(){AtomicInteger count=new AtomicInteger();PullRefreshLayout p=pull(new AtomicBoolean(true),count);send(p,0,100,40);send(p,2,100,70);send(p,1,100,70);assertEquals(0,count.get());}
 @Test public void cancellingPullDoesNotRefresh(){AtomicInteger count=new AtomicInteger();PullRefreshLayout p=pull(new AtomicBoolean(true),count);send(p,0,100,40);send(p,2,100,160);send(p,3,100,160);assertEquals(0,count.get());assertFalse(p.refreshing());}
 @Test public void pullCancelsPendingTrackMenu(){AtomicInteger held=new AtomicInteger(),click=new AtomicInteger(),refresh=new AtomicInteger();HoldListView list=list(held,click);((ViewGroup)list.getParent()).removeView(list);PullRefreshLayout p=new PullRefreshLayout(a,()->true,refresh::incrementAndGet);p.addView(list,0,new FrameLayout.LayoutParams(-1,-1));a.setContentView(p);size(p,400,600);send(p,0,30,25);send(p,2,30,170);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(500));assertEquals(0,held.get());send(p,1,30,170);assertEquals(1,refresh.get());}
 void waitFor(java.util.function.BooleanSupplier condition)throws Exception{long until=System.currentTimeMillis()+3000;while(!condition.getAsBoolean()&&System.currentTimeMillis()<until){Shadows.shadowOf(Looper.getMainLooper()).idle();Thread.sleep(10);}assertTrue(condition.getAsBoolean());Shadows.shadowOf(Looper.getMainLooper()).idle();}
 @Test public void duplicateCoversShareSingleRequest()throws Exception{AtomicInteger calls=new AtomicInteger();CountDownLatch release=new CountDownLatch(1);ArtworkLoader loader=new ArtworkLoader((url,edge)->{calls.incrementAndGet();release.await();return Bitmap.createBitmap(16,16,Bitmap.Config.RGB_565);});try{ImageView first=new ImageView(a),second=new ImageView(a);loader.bind(first,"same",128);loader.bind(second,"same",128);release.countDown();waitFor(()->loader.flightCount()==0&&loader.pendingCount()==0&&loader.cacheBytes()>0&&first.getDrawable()!=null&&second.getDrawable()!=null);assertEquals(1,calls.get());assertNotNull(first.getDrawable());assertNotNull(second.getDrawable());}finally{loader.close();}}
 @Test public void artworkQueueAndWorkersStayBounded()throws Exception{CountDownLatch started=new CountDownLatch(2),release=new CountDownLatch(1);ArtworkLoader loader=new ArtworkLoader((url,edge)->{started.countDown();release.await();return null;});try{loader.bind(new ImageView(a),"one",128);loader.bind(new ImageView(a),"two",128);assertTrue(started.await(2,TimeUnit.SECONDS));for(int i=0;i<80;i++)loader.bind(new ImageView(a),"queued"+i,128);assertTrue(loader.pendingCount()<=ArtworkLoader.MAX_PENDING);assertTrue(loader.flightCount()<=ArtworkLoader.WORKERS);}finally{release.countDown();loader.close();}}
 @Test public void stoppingImagesDropsLateResults()throws Exception{CountDownLatch started=new CountDownLatch(1),release=new CountDownLatch(1),finished=new CountDownLatch(1);ArtworkLoader loader=new ArtworkLoader((url,edge)->{started.countDown();release.await();finished.countDown();return Bitmap.createBitmap(16,16,Bitmap.Config.RGB_565);});try{ImageView image=new ImageView(a);loader.bind(image,"one",128);assertTrue(started.await(2,TimeUnit.SECONDS));loader.pause();release.countDown();assertTrue(finished.await(2,TimeUnit.SECONDS));Thread.sleep(30);Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(0,loader.cacheBytes());assertNull(image.getDrawable());}finally{release.countDown();loader.close();}}
 @Test public void thumbnailSamplingIsBounded(){assertTrue(500/OfflineArt.sample(500,500,128)<=128);assertTrue(8192/OfflineArt.sample(8192,8192,192)<=192);assertEquals(1,OfflineArt.sample(64,64,128));}
 @Test public void memoryPolicyUsesSmallFixedLimits(){assertEquals(2*1024*1024,ArtworkLoader.CACHE_BYTES);assertEquals(6*1024*1024,PlaybackMemory.TARGET_BYTES);assertNotNull(PlaybackMemory.control());assertTrue(PlaybackMemory.MAX_MS<=30000);}
 @Test public void allLibraryQueuesCycleTrackListOff(){assertTrue(RepeatPolicy.listContext("library"));assertFalse(RepeatPolicy.listContext("home"));assertFalse(RepeatPolicy.listContext("search"));assertEquals(1,RepeatPolicy.next(0,true));assertEquals(2,RepeatPolicy.next(1,true));assertEquals(0,RepeatPolicy.next(2,true));assertEquals(0,RepeatPolicy.next(1,false));}
 @Test public void downloadAnimationIsOwnerScopedAndStops(){String owner="164-test";DownloadActivityState.begin(owner);DownloadActivityState.begin(owner);DownloadIndicator icon=new DownloadIndicator(a);icon.setActive(DownloadActivityState.active(owner));assertTrue(icon.active());assertFalse(DownloadActivityState.active("other"));DownloadActivityState.end(owner);assertTrue(DownloadActivityState.active(owner));DownloadActivityState.end(owner);icon.setActive(DownloadActivityState.active(owner));assertFalse(icon.active());assertEquals("Загрузки",icon.getContentDescription());}
 @Test public void appNoticeIsInlineNotToast(){LinearLayout root=new LinearLayout(a);root.setOrientation(1);a.setContentView(root);org.robolectric.shadows.ShadowToast.reset();SoundFlowUi.notice(a,"Готово");assertNull(org.robolectric.shadows.ShadowToast.getTextOfLatestToast());TextView status=root.findViewWithTag("inline-status");assertNotNull(status);assertEquals("Готово",status.getText().toString());SoundFlowUi.notice(a,"Второе");assertEquals(1,root.getChildCount());}
}
